import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-button',
  standalone: true,
  template: `
    <button
      type="button"
      class="btn"
      [class.primary]="variant === 'primary'"
      [class.secondary]="variant === 'secondary'"
      [class.ghost]="variant === 'ghost'"
      [class.sm]="size === 'sm'"
      [class.md]="size === 'md'"
      [class.lg]="size === 'lg'"
      [class.is-loading]="loading"
      [attr.aria-disabled]="disabled || loading"
      [attr.aria-busy]="loading"
      [disabled]="disabled || loading"
      (click)="onClick($event)"
      (mousedown)="onPressStart()"
      (mouseup)="onPressEnd()"
      (mouseleave)="onPressEnd()"
      (touchstart)="onPressStart()"
      (touchend)="onPressEnd()"
    >
      <span *ngIf="!loading && icon_leading" class="icon" aria-hidden="true">{{ icon_leading }}</span>
      <span *ngIf="!loading" class="label">{{ label }}</span>
      <span *ngIf="loading" class="spinner" role="status" aria-label="loading"></span>
    </button>
  `,
  styles: [`
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      border-radius: 6px;
      border: 1px solid transparent;
      cursor: pointer;
      font-weight: 500;
      transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
    }
    .btn:disabled,
    .btn[aria-disabled='true'] {
      opacity: 0.55;
      cursor: not-allowed;
    }
    .btn.sm { padding: 4px 10px; font-size: 12px; }
    .btn.md { padding: 8px 14px; font-size: 14px; }
    .btn.lg { padding: 12px 20px; font-size: 16px; }
    .btn.primary { background: #2563eb; color: #fff; border-color: #2563eb; }
    .btn.secondary { background: #e5e7eb; color: #111827; border-color: #d1d5db; }
    .btn.ghost { background: transparent; color: #2563eb; border-color: transparent; }
    .btn.is-loading .label { visibility: hidden; }
    .spinner {
      width: 1em;
      height: 1em;
      border: 2px solid currentColor;
      border-right-color: transparent;
      border-radius: 50%;
      display: inline-block;
      animation: spin 0.7s linear infinite;
    }
    @keyframes spin { to { transform: rotate(360deg); } }
  `]
})
export class ButtonComponent {
  @Input() label: string = '';
  @Input() variant: 'primary' | 'secondary' | 'ghost' = 'primary';
  @Input() size: 'sm' | 'md' | 'lg' = 'md';
  @Input() disabled: boolean = false;
  @Input() loading: boolean = false;
  @Input() icon_leading?: string;

  @Output() pressed = new EventEmitter<void>();
  @Output() long_pressed = new EventEmitter<void>();

  private pressTimer: any = null;
  private readonly LONG_PRESS_MS = 500;

  onClick(event: Event): void {
    if (this.disabled || this.loading) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    this.pressed.emit();
  }

  onPressStart(): void {
    if (this.disabled || this.loading) {
      return;
    }
    this.clearPressTimer();
    this.pressTimer = setTimeout(() => {
      this.long_pressed.emit();
      this.pressTimer = null;
    }, this.LONG_PRESS_MS);
  }

  onPressEnd(): void {
    this.clearPressTimer();
  }

  private clearPressTimer(): void {
    if (this.pressTimer !== null) {
      clearTimeout(this.pressTimer);
      this.pressTimer = null;
    }
  }
}
